"""Compare a completed independent raw audit with the driver's later claims."""
from collections import Counter
import hashlib
import json
from pathlib import Path

BASE = Path(__file__).resolve().parents[1]
OUTPUT = BASE / 'benchmark/independent-resolver-probe-v1'
AUDIT = OUTPUT / 'independent-resolver-probe.json'
SUMMARY = BASE / 'diagnostic/resolver-variation/probe-v1/summary.json'


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    audited = json.loads(AUDIT.read_text())
    claimed = json.loads(SUMMARY.read_text())
    assert audited['valid'] and audited['queryCount'] == 52 and audited['jvmCount'] == 4
    assert claimed['complete'] and claimed['validatedQueryCount'] == 52
    assert claimed['completedAndValidatedJvms'] == 4 and not claimed['errors']
    assert not claimed['performanceInference'] and not claimed['acceptedTimingComparison']
    assert not claimed['originalTimingEventCauseEstablished']
    tiers, events = Counter(), Counter()
    changed = []
    ledger_changes = []
    for run, reported in zip(audited['runs'], claimed['runs'], strict=True):
        assert all(run[key] == reported[key] for key in ('runId', 'arm', 'queryCount'))
        for query, observation in zip(run['queries'], reported['observations'], strict=True):
            assert all(query[key] == observation[key] for key in ('sourceIdentity',
                'generatedMaterializerSha256', 'rawOwnerFile', 'rawOwnerSha256', 'stage', 'iteration',
                'resolverCalls', 'resolverDifferenceFromSameArmReference',
                'ordinaryPartition', 'terminalFactorMissPartition'))
            assert query['totals']['factorHit'] == observation['factorHits']
            assert query['totals']['pageRefused'] == observation['pageAdmissionRefusals']
            assert query['counters']['coordinateAdmissions'] == observation['coordinateAdmissionCounters']
            assert len(observation['targets']) == len(query['banks']) == 6
            assert [target['name'] for target in observation['targets']] == ['s', 'a', 'l0', 'l1', 'r0', 'r1']
            for target in observation['targets']:
                bank = query['banks'][target['name']]
                assert target['target'] == target['canonical'] == bank['canonicalIndex']
                assert target['ordinaryPartition'] == {key: bank['totals'][key] for key in query['ordinaryPartition']}
                assert target['terminalFactorMissPartition'] == {
                    key: bank['totals'][key] for key in query['terminalFactorMissPartition']}
                assert target['rememberCalls'] == bank['totals']['rememberCall']
                assert target['factorHits'] == bank['totals']['factorHit']
                assert target['pageAdmissionRefusals'] == bank['totals']['pageRefused']
                assert target['counterChangesFromSameArmReference'] == query[
                    'counterChangesFromSameArmReference'].get(target['name'], {})
            tiers.update({key: query['counters'][key] for key in ('compiledBinds', 'interpretedBinds',
                'aggregateCompiledBinds', 'aggregateInterpretedBinds')})
            events.update({key: query['totals'][key] for key in ('ordinaryWeakMiss', 'ordinaryWitnessMiss',
                'factorWeakMiss', 'factorWitnessMiss', 'pageRefused')})
            previous_peak = audited['references'][run['arm']]['query']['ledgerPeakBytes']
            if query['ledgerPeakBytes'] != previous_peak:
                ledger_changes.append({'runId': run['runId'], 'iteration': query['iteration'],
                    'before': previous_peak, 'observed': query['ledgerPeakBytes']})
            if query['counterChangesFromSameArmReference']:
                changed.append({'runId': run['runId'], 'arm': run['arm'],
                    **{key: query[key] for key in ('stage', 'iteration', 'resolverCalls',
                        'resolverDifferenceFromSameArmReference', 'terminalFactorMissPartition',
                        'counterChangesFromSameArmReference', 'rawOwnerFile', 'rawOwnerSha256')}})
    result = {'format': 1, 'valid': True, 'independentAuditFile': str(AUDIT),
        'independentAuditSha256': sha(AUDIT), 'driverSummaryFile': str(SUMMARY),
        'driverSummarySha256': sha(SUMMARY), 'scriptSha256': sha(Path(__file__)),
        'summaryMatchesIndependentRawCalculation': True, 'jvms': 4, 'queries': 52,
        'referenceQueries': 8, 'tiers': tiers, 'eventCounts': events, 'changedQueries': changed,
        'unchangedQueries': 52 - len(changed), 'runtimeEntriesRehashed': len(audited['runtimeManifest']),
        'ledgerPeakChangesFromReference': ledger_changes,
        'pinnedInputs': len(audited['sourceFiles']), 'processIntervalsSerial': True,
        'allResultRouteLedgerChecksPass': True, 'allFinalMissResolverPartitionsPass': True,
        'gcReferenceProcessingPresent': {run['runId']: run['gcLog']['referenceProcessingPresent']
            for run in audited['runs']}, 'performanceInference': False, 'acceptedTimingComparison': False,
        'originalTimingEventCauseEstablished': False}
    with (OUTPUT / 'summary-reconciliation.json').open('x') as stream:
        json.dump(result, stream, indent=2, sort_keys=True)
        stream.write('\n')
    lines = ['# Independently confirmed resolver-probe findings', '',
        'The fixed all/omit/omit/all diagnostic completed exactly four fresh JVMs and 52 queries. '
        'Independent raw reconciliation passed every query, all eight earlier same-arm reference queries, '
        'all four serial process intervals, the complete 130-entry runtime, and 113 pinned raw/source/reference inputs. '
        'The driver summary was checked only after the independent calculation and agrees exactly.', '',
        f"Native execution comprised {tiers['interpretedBinds']} interpreted and {tiers['compiledBinds']} compiled binds, "
        'with zero aggregate-tier binds. Every result oracle, normal AUTO/native route, adjacency revision, root-host audit, '
        'page grant/release identity, and zero query-ledger endpoint passed.', '',
        '## Changed observations', '',
        '| Run | Stage | Iteration | Resolver calls | Delta from same-arm reference |',
        '| --- | --- | ---: | ---: | ---: |']
    for query in changed:
        lines.append(f"| {query['runId']} | {query['stage']} | {query['iteration']} | "
            f"{query['resolverCalls']:,} | +{query['resolverDifferenceFromSameArmReference']} |")
    lines += ['', f'The remaining {52-len(changed)} queries have 32,833 resolver calls and reference-identical '
        'materializer counters. In each changed query, only `r1` differs:', '']
    delta_sets = [query['counterChangesFromSameArmReference'] for query in changed]
    if delta_sets and all(delta == delta_sets[0] for delta in delta_sets):
        for target, changes in delta_sets[0].items():
            lines += [f'- `{target}.{key}`: {value:+d}.' for key, value in sorted(changes.items())]
    lines += ['', 'Each changed query has the exclusive final-factor miss decomposition '
        '`69 initial + 24,700 absent-page + 8,064 absent/mismatched-cell + 1 cleared-weak + 0 witness = 32,834`. '
        'This reconciles globally with resolvers and per target with remember calls. '
        'All other target counters and final page counts/occupancy match the same-arm reference. '
        + ('All ledger peaks also match that reference.' if not ledger_changes else
           'Observed ledger-peak changes are preserved separately in the reconciliation JSON.'), '',
        f"Across all 52 queries, ordinary weak branches total {events['ordinaryWeakMiss']}, ordinary witness branches "
        f"{events['ordinaryWitnessMiss']}, final factor weak branches {events['factorWeakMiss']}, final factor witness "
        f"branches {events['factorWitnessMiss']}, and page-admission refusals {events['pageRefused']}.", '',
        '## What this establishes', '',
        'The two new instrumented queries each reached the existing final-factor cleared-weak branch once, '
        'then resolved and republished the value instead of recording one factor hit. '
        'Ordinary and factor weak events remain separate; their counts are never added as extra resolutions. '
        'No witness or refusal event explains these two probe differences.', '',
        'All four JVM logs declare G1 and contain reference-processing messages, with no explicit System.gc() text. '
        'The logs are not aligned to individual queries or referents. The unchanged diagnostic helper itself changes '
        'allocation and close-time work, so these observations do not establish natural miss rates or any arm-performance ranking. '
        'They also do not prove the cause of the earlier uninstrumented timing event.', '',
        'The original primary timing protocol remains failed and incomplete at nine JVMs/117 queries. '
        'No performance ratios, replacements, extensions, relaxed gates, or production promotion follow from this probe.', '',
        'Full raw-file identities, all 52 query decompositions, and all per-target counter changes are preserved in '
        '`independent-resolver-probe.json`; the later claim comparison is `summary-reconciliation.json`.', '']
    with (OUTPUT / 'findings.md').open('x') as stream:
        stream.write('\n'.join(lines))
    print(json.dumps({'valid': True, 'changedQueries': len(changed), 'summaryMatches': True,
        'tiers': tiers, 'events': events, 'output': str(OUTPUT)}))


if __name__ == '__main__':
    main()
